const $=s=>document.querySelector(s);
const menu=$('.menu-toggle'),nav=$('#primaryNav');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));nav.classList.toggle('open',open)});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');$('.products-menu').open=false}});
document.addEventListener('click',e=>{if(!e.target.closest('.products-menu'))$('.products-menu').open=false});
const need=$('#solutionNeed');if(need)need.addEventListener('change',()=>{const a=$('#solutionResult');a.href=need.value;a.textContent='Explore this solution'});
const params=new URLSearchParams(location.search);if($('#rateProduct')&&[...$('#rateProduct').options].some(o=>o.value===params.get('product')))$('#rateProduct').value=params.get('product');
function prepareEmail(link,subject,text,to='sales@blucapital.us'){link.href='mailto:'+to+'?subject='+encodeURIComponent(subject)+'&body='+encodeURIComponent(text)}
async function copyText(text,status){try{await navigator.clipboard.writeText(text);status.textContent='Request copied.'}catch{status.textContent='Select and copy the request above.'}}
const rateForm=$('#rateForm');if(rateForm){let text='';rateForm.addEventListener('submit',e=>{e.preventDefault();if(!rateForm.reportValidity())return;const d=new FormData(rateForm),product=$('#rateProduct').selectedOptions[0].text;text=`Hello Blu Capital,\n\nI would like a personalized financing rate.\n\nCompany: ${d.get('company').trim()}\nName: ${d.get('name').trim()}\nEmail: ${d.get('email').trim()}\nPhone: ${d.get('phone').trim()}\nProduct: ${product}\nAmount needed: ${d.get('amount')}\n\nPlease contact me about available options and the application requirements.\n\nThank you.`;$('#ratePreview').textContent=text;prepareEmail($('#rateSend'),'Financing rate inquiry: '+d.get('company').trim(),text);$('#rateResult').hidden=false;$('#rateResult').scrollIntoView({block:'nearest'})});rateForm.addEventListener('input',()=>{$('#rateResult').hidden=true;$('#rateStatus').textContent=''});$('#rateCopy').addEventListener('click',()=>copyText(text,$('#rateStatus')))}
const callbackForm=$('#callbackForm');if(callbackForm){let text='';const date=$('#callbackDate');callbackForm.addEventListener('submit',e=>{e.preventDefault();const d=new FormData(callbackForm);const parts=Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:d.get('timezone'),year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date()).map(p=>[p.type,p.value]));const zonedNow=`${parts.year}-${parts.month}-${parts.day}T${parts.hour}:${parts.minute}`;date.setCustomValidity(`${d.get('date')}T${d.get('time')}`<=zonedNow?'Please select a future date and time.':'');if(!callbackForm.reportValidity())return;text=`Hello Blu Capital,\n\nPlease contact me to arrange a conversation.\n\nName: ${d.get('name').trim()}\nEmail: ${d.get('email').trim()}\nPhone: ${d.get('phone').trim()}\nPreferred date: ${d.get('date')}\nPreferred time: ${d.get('time')}\nTimezone: ${d.get('timezone')}\n\n${d.get('topic').trim()}\n\nPlease confirm availability. I understand this is a request, not a confirmed booking.`;$('#callbackPreview').textContent=text;prepareEmail($('#callbackSend'),'Callback request',text);$('#callbackResult').hidden=false;$('#callbackResult').scrollIntoView({block:'nearest'})});callbackForm.addEventListener('input',()=>{date.setCustomValidity('');$('#callbackResult').hidden=true;$('#callbackStatus').textContent=''});$('#callbackCopy').addEventListener('click',()=>copyText(text,$('#callbackStatus')))}
const contactForm=$('#conversationForm');if(contactForm){const offices={plano:{name:'Plano',email:'hi@blucapital.com',phone:'+12148760504',display:'(214) 876 0504'},elpaso:{name:'El Paso',email:'sales@blucapital.us',phone:'+19157277883',display:'(915) 727 7883'}},office=$('#contactOffice'),service=$('#contactService');let text='';function refresh(){const o=offices[office.value];$('#directPhone').href='tel:'+o.phone;$('#directPhone').textContent=o.name+': '+o.display;$('#directEmail').href='mailto:'+o.email;$('#directEmail').textContent=o.email}office.addEventListener('change',refresh);refresh();contactForm.addEventListener('submit',e=>{e.preventDefault();if(!contactForm.reportValidity())return;const d=new FormData(contactForm),o=offices[d.get('office')];text=`Hello Blu Capital,\n\nI would like to discuss ${service.selectedOptions[0].text.toLowerCase()}.\n\nName: ${d.get('name').trim()}\nBusiness: ${d.get('company').trim()}\nEmail: ${d.get('email').trim()}${d.get('phone').trim()?'\nPhone: '+d.get('phone').trim():''}\nPreferred office: ${o.name}\n\n${d.get('message').trim()}\n\nThank you.`;const link=$('#sendMessageLink');if(d.get('channel')==='whatsapp'){link.href='https://wa.me/12148760504?text='+encodeURIComponent(text);link.target='_blank';link.rel='noopener';link.textContent='Continue in WhatsApp';$('#handoffInstructions').textContent='Review your message in Blu’s Plano sales WhatsApp and press Send. Your message has not been sent.'}else{prepareEmail(link,'Business financing inquiry: '+d.get('company').trim(),text,o.email);link.removeAttribute('target');link.removeAttribute('rel');link.textContent='Open email draft';$('#handoffInstructions').textContent='Review the draft to '+o.email+' in your email app and press Send. If no email app opens, copy the message and email it to that address.'}$('#messagePreview').textContent=text;$('#contactHandoff').hidden=false;$('#handoffTitle').focus()});contactForm.addEventListener('input',()=>{$('#contactHandoff').hidden=true;$('#copyStatus').textContent=''});contactForm.addEventListener('change',()=>{$('#contactHandoff').hidden=true});$('#copyMessage').addEventListener('click',()=>copyText(text,$('#copyStatus')))}
// Preserve existing shared anchors while routing visitors to the new dedicated pages.
if(location.pathname==='/'||location.pathname.endsWith('/index.html')){const legacy={'#contact':'contact.html','#application':'apply.html','#schedule':'contact.html#callback','#rate-inquiry':'get-rate.html','#solutions':'solutions.html','#finder':'solutions.html#finder','#about':'about.html','#company':'about.html','#careers':'careers.html','#questions':'requirements.html','#offices':'contact.html','#how':'requirements.html'};if(legacy[location.hash])location.replace(legacy[location.hash])}
const applicationInquiry=$('#applicationInquiry');if(applicationInquiry){let step=0,text='';const fieldsets=[...applicationInquiry.querySelectorAll('[data-application-step]')],progress=[...document.querySelectorAll('.application-progress li')],next=$('#applicationNext'),back=$('#applicationBack');function fields(){return Object.fromEntries([...applicationInquiry.querySelectorAll('input[name],select[name],textarea[name]')].map(e=>[e.name,e.value.trim()]))}function review(){const d=fields(),host=$('#applicationReview');host.replaceChildren();for(const [key,label] of [['company','Business'],['industry','Industry'],['product','Financing'],['amount','Amount'],['name','Name'],['email','Email'],['phone','Phone'],['goals','Your goal']]){if(!d[key])continue;const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=d[key];host.append(dt,dd)}text=`Hello Blu Capital,\n\nI would like to discuss financing for my business.\n\nBusiness: ${d.company}\nIndustry: ${d.industry}\nFinancing: ${d.product}\nAmount needed: ${d.amount}\nName: ${d.name}\nEmail: ${d.email}\nPhone: ${d.phone}${d.goals?'\n\nGoal: '+d.goals:''}\n\nPlease contact me with available options and application requirements.\n\nThank you.`;prepareEmail($('#applicationSend'),'Financing inquiry: '+d.company,text);$('#applicationStatus').textContent=''}function showStep(n){step=n;fieldsets.forEach((f,i)=>{f.hidden=i!==step;f.disabled=i!==step});progress.forEach((p,i)=>{p.classList.toggle('current',i===step);p.classList.toggle('completed',i<step);if(i===step)p.setAttribute('aria-current','step');else p.removeAttribute('aria-current')});next.hidden=step===2;back.hidden=step===0;next.textContent=step===1?'Review inquiry':'Continue';$('#applicationStepLabel').textContent=`Step ${step+1} of 3`;if(step===2)review();const legend=fieldsets[step].querySelector('legend');legend.tabIndex=-1;legend.focus()}function advance(){for(const e of fieldsets[step].querySelectorAll('input,select,textarea')){if(e.required&&e.type!=='email')e.setCustomValidity(e.value.trim()?'':'Please complete this field.');if(!e.reportValidity())return}if(step<2)showStep(step+1)}next.addEventListener('click',advance);back.addEventListener('click',()=>showStep(step-1));applicationInquiry.addEventListener('submit',e=>{e.preventDefault();if(step<2)advance()});applicationInquiry.addEventListener('input',e=>{if(e.target.setCustomValidity)e.target.setCustomValidity('')});$('#applicationCopy').addEventListener('click',()=>copyText(text,$('#applicationStatus')));const dialog=$('#secureApplication'),frame=$('#secureApplicationFrame');let opener=null;document.querySelectorAll('.secure-open').forEach(b=>b.addEventListener('click',()=>{opener=b;if(!frame.src)frame.src=frame.dataset.src;dialog.showModal()}));$('#secureClose').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>opener?.focus());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}})}
const contactTabs=[...document.querySelectorAll('.contact-tabs [role="tab"]')];if(contactTabs.length){function activateContactTab(tab,focus=false){for(const t of contactTabs){const selected=t===tab;t.setAttribute('aria-selected',String(selected));t.tabIndex=selected?0:-1;document.getElementById(t.getAttribute('aria-controls')).hidden=!selected}if(focus)tab.focus()}contactTabs.forEach((tab,i)=>{tab.addEventListener('click',()=>activateContactTab(tab));tab.addEventListener('keydown',e=>{let n;if(e.key==='ArrowRight')n=(i+1)%contactTabs.length;if(e.key==='ArrowLeft')n=(i-1+contactTabs.length)%contactTabs.length;if(e.key==='Home')n=0;if(e.key==='End')n=contactTabs.length-1;if(n!==undefined){e.preventDefault();activateContactTab(contactTabs[n],true)}})});function fromHash(){if(location.hash==='#callback'){activateContactTab(document.getElementById('callbackTab'));document.getElementById('callback').scrollIntoView({block:'start'})}}fromHash();window.addEventListener('hashchange',fromHash)}
// Keep links as ordinary same-tab navigation so embedded mobile browsers do not need popup support.
nav.addEventListener('click',e=>{if(e.target.closest('a')){nav.classList.remove('open');menu.setAttribute('aria-expanded','false')}});
const resumeLink=$('#resumeLink'),careersDialog=$('#careersEmailDialog');if(resumeLink&&careersDialog){resumeLink.addEventListener('click',e=>{if(typeof careersDialog.showModal!=='function')return;e.preventDefault();careersDialog.showModal()});$('#careersEmailClose').addEventListener('click',()=>careersDialog.close());careersDialog.addEventListener('close',()=>resumeLink.focus());careersDialog.addEventListener('click',e=>{if(e.target===careersDialog){const r=careersDialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)careersDialog.close()}});$('#careersEmailCopy').addEventListener('click',async()=>{const input=$('#careersEmailAddress'),status=$('#careersEmailStatus');try{await navigator.clipboard.writeText(input.value);status.textContent='Email address copied. Paste it into your email app and attach your résumé.'}catch{input.focus();input.select();input.setSelectionRange(0,input.value.length);try{if(document.execCommand('copy')){status.textContent='Email address copied. Paste it into your email app and attach your résumé.';return}}catch{}status.textContent='Press and hold the selected address to copy it, then paste it into your email app.'}})}
